/**
 * CITY SUBSURFACE — frame preload for arizona.
 *
 * Generated by scripts/build-city-subsurface.mjs. Statically imports the
 * active frame's data + gazetteer packs (and DEM grid, when present) and
 * exposes them on globalThis so js/city-subsurface.js can boot with ZERO
 * top-level-await and ZERO boot-time dynamic imports. Several Webxdc host
 * webviews fail to parse (top-level await) or evaluate (dynamic import)
 * those at module scope, which froze every frame before the first render
 * while socal (fully static imports) kept working. Module scripts execute
 * in document order, so this file always runs before the engine entry.
 */
import * as data from "./city-subsurface-data-arizona.js";
import * as gaz from "./city-gazetteer-data-arizona.js";

globalThis.__CITY_FRAME_PRELOAD__ = { id: "arizona", data, gaz, dem: null };
